def match_parens(lst):
    def backtrack(index):
        if index == len(lst):
            return is_balanced(''.join(lst))

        for i in range(index, len(lst)):
            lst[index], lst[i] = lst[i], lst[index]
            if backtrack(index + 1):
                return True
            lst[index], lst[i] = lst[i], lst[index]

        return False

    if backtrack(0):
        return 'Yes'
    else:
        return 'No'

